questionvariables.text:
dec(v) := block([k:0], while k<10 and not(integerp(ev(10^k*v,simp))) do k:k+1, if k=0 then string(v) else dispdp(float(v),k));
pad3(r) := if r<10 then sconcat("00",r) else if r<100 then sconcat("0",r) else sconcat(r);
grp(v) := if v<0 then sconcat("-",grp(-v)) else if v<10000 then sconcat(v) else sconcat(floor(v/1000),"\\,",pad3(mod(v,1000)));
money(v) := block([c], c: floor(100*v+1/2), if mod(c,100)=0 then grp(c/100) else sconcat(grp(floor(c/100)),".",if mod(c,100)<10 then sconcat("0",mod(c,100)) else sconcat(mod(c,100))));
/* Design: find-the-mistake pattern. Source: original. er 1: row for power n-1 (step 2); er 2: x^2 and x^3 with one zero too few (step 3); er 3: the x^3 term given a + sign (step 4). Later steps follow correctly from the wrong one. */
L: [[5,2/100,1],[7,2/100,2],[8,2/100,3],[5,3/100,1],[7,3/100,2],[5,4/100,3],[9,2/100,1],[8,3/100,2],[5,5/100,3],[7,4/100,2]];
ix: 1+rand(10);
n: L[ix][1];
d: L[ix][2];
er: L[ix][3];
xv: -d;
m: if er=1 then n-1 else n;
cs: [binomial(m,1),binomial(m,2),binomial(m,3)];
x2s: if er=2 then 10*xv^2 else xv^2;
x3s: if er=2 then 10*xv^3 else xv^3;
tt: [cs[1]*xv, cs[2]*x2s, (if er=3 then -1 else 1)*cs[3]*x3s];
Ss: 1+apply("+",tt);
Rs: floor(10^4*Ss+1/2)/10^4;
S4: sum(binomial(n,r)*xv^r,r,0,3);
two: 1+n*xv;
Nd: dispdp(float(1-d),2);
dd: dispdp(float(d),2);
x2d: dec(x2s); x3d: dec(x3s);
ttd: map(dec, tt);
Sd: dec(Ss);
Rd: dispdp(float(Rs),4);
cx2: dec(xv^2); cx3: dec(xv^3);
ct: makelist(dec(binomial(n,r)*xv^r),r,1,3);
S4d: dec(S4);
R4: dispdp(float(floor(10^4*S4+1/2)/10^4),4);
C1: n; C2: binomial(n,2); C3: binomial(n,3);
opts: [["s1",false,"Step 1"],["s2",is(er=1),"Step 2"],["s3",is(er=2),"Step 3"],["s4",is(er=3),"Step 4"],["s5",false,"Step 5"],["s6",false,"Step 6"]];
kq: first(mcq_correct(opts));
wr: if er=1 then "s3" else "s2";
wstep: er+1;
